"use client";

import { cn } from "@/lib/utils";
import { useEffect, useRef } from "react";
import { getThemeStyles } from "./date-picker-theme";
import { setTime, type TimeFormat } from "./time-picker-utils";

export type { TimeFormat };

export interface TimePickerProps {
  /** The date whose time is being edited. The day part is preserved on change. */
  value: Date | null;
  /** Receives a copy of `value` with the new hours / minutes applied. */
  onChange: (next: Date) => void;
  /** 12-hour clock with an AM / PM column, or a 24-hour one. Default "12h". */
  format?: TimeFormat;
  /** Minute granularity. Default 5. */
  minuteStep?: number;
  /** Times earlier than this are disabled (compared on the same day as `value`). */
  minTime?: Date | null;
  /** Times later than this are disabled (compared on the same day as `value`). */
  maxTime?: Date | null;
  /** Theme colour — same names / hex codes as the date pickers. */
  color?: string;
  disabled?: boolean;
  className?: string;
}

const pad = (n: number) => String(n).padStart(2, "0");

// One scrollable column of options. Keeps the selected item centred so the
// picker opens on the current value instead of at the top of the list.
function Column<T extends string | number>({
  items,
  selected,
  isDisabled,
  onSelect,
  render,
  theme,
  disabled,
  label,
}: {
  items: T[];
  selected: T | null;
  isDisabled: (item: T) => boolean;
  onSelect: (item: T) => void;
  render: (item: T) => string;
  theme: Record<string, string>;
  disabled: boolean;
  label: string;
}) {
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const list = listRef.current;
    if (!list || selected === null) return;
    const el = list.querySelector<HTMLElement>(`[data-value="${selected}"]`);
    if (!el) return;
    // Scroll the column itself, never the page.
    list.scrollTop = el.offsetTop - list.clientHeight / 2 + el.clientHeight / 2;
  }, [selected]);

  return (
    <div
      ref={listRef}
      role="listbox"
      aria-label={label}
      // shrink-0: a tight parent must never squeeze a column narrower than its
      // buttons — that is exactly what produces a horizontal scrollbar here.
      className="relative h-full shrink-0 overflow-y-auto overflow-x-hidden overscroll-contain px-0.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
    >
      <div className="flex flex-col gap-0.5 py-1">
        {items.map((item) => {
          const active = item === selected;
          const off = disabled || isDisabled(item);
          return (
            <button
              key={item}
              type="button"
              role="option"
              aria-selected={active}
              data-value={item}
              disabled={off}
              onClick={(e) => {
                e.stopPropagation();
                onSelect(item);
              }}
              className={cn(
                "w-10 h-7 shrink-0 rounded-md text-xs font-semibold tabular-nums transition-colors",
                active
                  ? cn(theme.bg, "shadow-sm")
                  : "text-foreground hover:bg-muted",
                off && "opacity-30 cursor-not-allowed hover:bg-transparent",
              )}
            >
              {render(item)}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function TimePicker({
  value,
  onChange,
  format = "12h",
  minuteStep = 5,
  minTime,
  maxTime,
  color = "primary",
  disabled = false,
  className,
}: TimePickerProps) {
  const { theme, style } = getThemeStyles(color);
  const is12h = format === "12h";

  const hours24 = value ? value.getHours() : null;
  const minutes = value ? value.getMinutes() : null;
  const period: "AM" | "PM" | null = hours24 === null ? null : hours24 >= 12 ? "PM" : "AM";
  const hour12 = hours24 === null ? null : hours24 % 12 === 0 ? 12 : hours24 % 12;

  const hourItems = is12h
    ? Array.from({ length: 12 }, (_, i) => i + 1)
    : Array.from({ length: 24 }, (_, i) => i);
  const minuteItems = Array.from({ length: Math.ceil(60 / minuteStep) }, (_, i) => i * minuteStep);

  const to24 = (h: number, p: "AM" | "PM" | null) => {
    if (!is12h) return h;
    const base = h % 12;
    return (p ?? "AM") === "PM" ? base + 12 : base;
  };

  // A candidate time is out of bounds if it falls before minTime or after
  // maxTime on the same day. Without a value there is no day to compare on,
  // so nothing is disabled.
  const outOfBounds = (h24: number, m: number) => {
    if (!value) return false;
    const t = setTime(value, h24, m).getTime();
    if (minTime && t < minTime.getTime()) return true;
    if (maxTime && t > maxTime.getTime()) return true;
    return false;
  };
  const hourDisabled = (h: number, p = period) => {
    const h24 = to24(h, p);
    return minuteItems.every((m) => outOfBounds(h24, m));
  };
  const minuteDisabled = (m: number) =>
    hours24 === null ? false : outOfBounds(hours24, m);
  const periodDisabled = (p: "AM" | "PM") => hourItems.every((h) => hourDisabled(h, p));

  const commit = (h24: number, m: number) => {
    if (!value) return;
    onChange(setTime(value, h24, m));
  };

  // When the current minute becomes invalid for a newly chosen hour (or
  // period), snap to the first minute that is allowed in it.
  const firstValidMinute = (h24: number) =>
    minuteItems.find((m) => !outOfBounds(h24, m)) ?? minuteItems[0];

  return (
    <div
      className={cn("flex items-stretch justify-center gap-1 h-32 min-w-max", className)}
      style={style}
      aria-disabled={disabled}
    >
      <Column
        label="Hour"
        items={hourItems}
        selected={is12h ? hour12 : hours24}
        isDisabled={(h) => hourDisabled(h)}
        onSelect={(h) => {
          const h24 = to24(h, period);
          const m = minutes ?? 0;
          commit(h24, outOfBounds(h24, m) ? firstValidMinute(h24) : m);
        }}
        render={(h) => pad(h)}
        theme={theme}
        disabled={disabled || !value}
      />
      <span className="self-center text-sm font-semibold text-muted-foreground">:</span>
      <Column
        label="Minute"
        items={minuteItems}
        selected={minutes !== null ? minutes - (minutes % minuteStep) : null}
        isDisabled={minuteDisabled}
        onSelect={(m) => commit(hours24 ?? 0, m)}
        render={(m) => pad(m)}
        theme={theme}
        disabled={disabled || !value}
      />
      {is12h && (
        <Column<"AM" | "PM">
          label="AM or PM"
          items={["AM", "PM"]}
          selected={period}
          isDisabled={periodDisabled}
          onSelect={(p) => {
            const h24 = to24(hour12 ?? 12, p);
            const m = minutes ?? 0;
            commit(h24, outOfBounds(h24, m) ? firstValidMinute(h24) : m);
          }}
          render={(p) => p}
          theme={theme}
          disabled={disabled || !value}
        />
      )}
    </div>
  );
}

"use client";

import React from "react";

const colorThemes: Record<string, Record<string, string>> = {
  primary: {
    ring: "focus-within:ring-primary/30 focus-within:border-primary/30",
    text: "text-primary",
    bg: "bg-primary text-primary-foreground hover:bg-primary/90",
    bgSoft:
      "bg-primary/10 text-foreground hover:bg-primary/20",
    glow: "focus-within:shadow-[0_0_20px_var(--primary)] focus-within:border-primary/30",
  },
  indigo: {
    ring: "focus-within:ring-indigo-500/30 focus-within:border-indigo-500",
    text: "text-indigo-600 dark:text-indigo-400",
    bg: "bg-indigo-600 text-white hover:bg-indigo-700",
    bgSoft:
      "bg-indigo-50 dark:bg-indigo-500/10 text-indigo-900 dark:text-indigo-100 hover:bg-indigo-100 dark:hover:bg-indigo-500/20",
    glow: "focus-within:shadow-[0_0_20px_rgba(99,102,241,0.4)] focus-within:border-indigo-500",
  },
  rose: {
    ring: "focus-within:ring-rose-500/30 focus-within:border-rose-500",
    text: "text-rose-600 dark:text-rose-400",
    bg: "bg-rose-600 text-white hover:bg-rose-700",
    bgSoft:
      "bg-rose-50 dark:bg-rose-500/10 text-rose-900 dark:text-rose-100 hover:bg-rose-100 dark:hover:bg-rose-500/20",
    glow: "focus-within:shadow-[0_0_20px_rgba(244,63,94,0.4)] focus-within:border-rose-500",
  },
  emerald: {
    ring: "focus-within:ring-emerald-500/30 focus-within:border-emerald-500",
    text: "text-emerald-600 dark:text-emerald-400",
    bg: "bg-emerald-600 text-white hover:bg-emerald-700",
    bgSoft:
      "bg-emerald-50 dark:bg-emerald-500/10 text-emerald-900 dark:text-emerald-100 hover:bg-emerald-100 dark:hover:bg-emerald-500/20",
    glow: "focus-within:shadow-[0_0_20px_rgba(16,185,129,0.4)] focus-within:border-emerald-500",
  },
  zinc: {
    ring: "focus-within:ring-zinc-500/30 focus-within:border-zinc-500 dark:focus-within:ring-white/20 dark:focus-within:border-white",
    text: "text-zinc-900 dark:text-zinc-100",
    bg: "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 hover:bg-zinc-800 dark:hover:bg-zinc-200",
    bgSoft:
      "bg-zinc-100 dark:bg-zinc-800/50 text-zinc-900 dark:text-zinc-100 hover:bg-zinc-200 dark:hover:bg-zinc-800",
    glow: "focus-within:shadow-[0_0_20px_rgba(255,255,255,0.15)] focus-within:border-zinc-900 dark:focus-within:border-white",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        ring: "focus-within:ring-[var(--theme-color)]/30 focus-within:border-[var(--theme-color)]",
        text: "text-[var(--theme-color)]",
        bg: "bg-[var(--theme-color)] text-white hover:opacity-90",
        bgSoft:
          "bg-[rgba(var(--theme-color-rgb),0.1)] text-[var(--theme-color)] hover:bg-[rgba(var(--theme-color-rgb),0.2)]",
        glow: "focus-within:shadow-[0_0_20px_rgba(var(--theme-color-rgb),0.5)] focus-within:border-[var(--theme-color)]",
      },
      style: {
        "--theme-color": color,
        "--theme-color-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] || colorThemes.primary, style: {} };
};

export type TimeFormat = "12h" | "24h";

/** A new Date on the same day as `base` at the given time. */
export const setTime = (base: Date, hours: number, minutes: number) => {
  const next = new Date(base);
  next.setHours(hours, minutes, 0, 0);
  return next;
};

/** Rounds `date` up to the next multiple of `step` minutes — "now" for a picker default. */
export const roundToStep = (date: Date, step: number) => {
  const next = new Date(date);
  const m = Math.ceil(next.getMinutes() / step) * step;
  next.setMinutes(m, 0, 0);
  return next;
};

export const formatTime = (date: Date, format: TimeFormat = "12h") =>
  new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: format === "12h",
  }).format(date);
